xTicks.forEach(tick => {
const x = crispCoord(tick.pixel);
if (x > plotArea.left && x < plotArea.right) {
ctx.moveTo(x, plotArea.top);
ctx.lineTo(x, plotArea.bottom);
}
});
ctx.stroke();
ctx.setLineDash([]);
