let top = absY - 10;


if (left + tw > vw - 8) {
left = absX - tw - 15;
}

if (left < 8) {
left = 8;
}

if (top + th > vh - 8) {
top = absY - th - 10;
}

if (top < 8) {
top = 8;
}

