(function(global) {
var CZ = global.CZ;


var czChart = {

version: '1.0.0',


create: function(target, config) {
return new CZ.Chart(target, config);
},


use: function(plugin) {
CZ.Chart.use(plugin);
},


themes: {
light: CZ.LightTheme,
dark: CZ.DarkTheme
},


plugins: {
ThresholdLine: CZ.ThresholdLinePlugin,
Watermark: CZ.WatermarkPlugin
},


Easing: CZ.Easing,


_internal: CZ
};


global.czChart = czChart;





})(typeof window !== 'undefined' ? window : this);

